import type { System } from '../../Engine/System';
import type { World } from '../../Engine/World';
import type { BuildingEntity } from '../Entity/BuildingEntity';

export class ProduceSystem implements System {

    onTick(world: World, dt: number): void {
        for (const b of world.query<BuildingEntity>('building')) {
            if (b.effectiveIncomePerSecond <= 0) continue;
            b.pendingIncome = Math.min(
                b.pendingIncome + b.effectiveIncomePerSecond * dt,
                b.effectiveIncomeCap,
            );
        }
    }
}